@Override public GradientUpdaterAggregator combine(GradientUpdaterAggregator other){
  if (!(other instanceof AdaGradAggregator))   throw new IllegalArgumentException("Cannot combine AdaGradAggregator with aggregator: " + other);
  AdaGradAggregator aggregator=(AdaGradAggregator)other;
  historicalGradientSum.addi(aggregator.historicalGradientSum);
  lrSum+=aggregator.lrSum;
  numIterationsSum+=aggregator.numIterationsSum;
  count+=aggregator.count;
  return this;
}
